@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SettingsScreen(viewModel: DailyListViewModel = viewModel()) {
    val context = LocalContext.current
    val settings by viewModel.settings.collectAsState()
    val scope = rememberCoroutineScope()

    var canScheduleExact by remember { mutableStateOf(ExactAlarmScheduler.canScheduleExact(context)) }
    val lifecycleOwner = LocalLifecycleOwner.current
    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            if (event == Lifecycle.Event.ON_RESUME) {
                canScheduleExact = ExactAlarmScheduler.canScheduleExact(context)
            }
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
    }

    var importResult by remember { mutableStateOf<String?>(null) }
    var aiJsonInput by remember { mutableStateOf("") }
    var aiImportResult by remember { mutableStateOf<String?>(null) }
    var showAiImportConfirmDialog by remember { mutableStateOf(false) }
    var backupExpanded by remember { mutableStateOf(false) }
    val clipboard = LocalClipboard.current

    val exportLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.CreateDocument("application/json"),
    ) { uri ->
        if (uri != null) {
            viewModel.exportBackupJson { json ->
                scope.launch(Dispatchers.IO) {
                    context.contentResolver.openOutputStream(uri)?.use { it.write(json.toByteArray()) }
                }
            }
        }
    }

    val importLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.OpenDocument(),
    ) { uri ->
        if (uri != null) {
            scope.launch(Dispatchers.IO) {
                val json = context.contentResolver.openInputStream(uri)?.use { it.readBytes().decodeToString() }
                if (json != null) {
                    viewModel.restoreBackupJson(json) { errors ->
                        importResult = if (errors.isEmpty()) {
                            context.getString(R.string.backup_restored)
                        } else {
                            errors.joinToString("\n")
                        }
                    }
                } else {
                    importResult = context.getString(R.string.could_not_read_file)
                }
            }
        }
    }

    val performAiImport: () -> Unit = {
        viewModel.importAiSetupJson(aiJsonInput) { errors, profilesAdded, medicationsAdded ->
            aiImportResult = if (errors.isEmpty()) {
                aiJsonInput = ""
                context.getString(R.string.ai_import_summary, profilesAdded, medicationsAdded)
            } else {
                errors.joinToString("\n")
            }
        }
    }

    Scaffold(topBar = { TopAppBar(title = { Text(stringResource(R.string.settings_label)) }) }) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .imePadding()
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.fillMaxWidth(),
            ) {
                Text(stringResource(R.string.dose_reminder_notifications), modifier = Modifier.weight(1f))
                Switch(
                    checked = settings.notificationsEnabled,
                    onCheckedChange = { viewModel.setNotificationsEnabled(it) },
                )
            }

            if (!canScheduleExact) {
                Text(
                    stringResource(R.string.exact_alarm_warning),
                    style = MaterialTheme.typography.bodyMedium,
                    modifier = Modifier.padding(top = 16.dp),
                )
                Button(
                    onClick = {
                        val intent = Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM).apply {
                            data = Uri.parse("package:${context.packageName}")
                        }
                        context.startActivity(intent)
                    },
                    modifier = Modifier.padding(top = 8.dp),
                ) {
                    Text(stringResource(R.string.grant_exact_alarm_access))
                }
            }

            Text(
                stringResource(R.string.ai_assisted_setup),
                style = MaterialTheme.typography.titleMedium,
                modifier = Modifier.padding(top = 32.dp),
            )
            Text(
                stringResource(R.string.settings_ai_setup_body),
                style = MaterialTheme.typography.bodyMedium,
                modifier = Modifier.padding(top = 4.dp),
            )
            Button(
                onClick = {
                    scope.launch {
                        clipboard.setClipEntry(
                            ClipEntry(
                                ClipData.newPlainText(
                                    context.getString(R.string.ai_setup_prompt_clip_label),
                                    AI_SETUP_PROMPT.trim(),
                                ),
                            ),
                        )
                    }
                },
                modifier = Modifier.padding(top = 8.dp),
            ) {
                Text(stringResource(R.string.copy_setup_prompt))
            }
            OutlinedTextField(
                value = aiJsonInput,
                onValueChange = { aiJsonInput = it },
                label = { Text(stringResource(R.string.paste_ai_json_label)) },
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 16.dp),
                minLines = 4,
            )
            Button(
                onClick = {
                    if (aiJsonInput.isNotBlank()) {
                        showAiImportConfirmDialog = true
                    } else {
                        performAiImport()
                    }
                },
                modifier = Modifier.padding(top = 8.dp),
            ) {
                Text(stringResource(R.string.import_button))
            }
            aiImportResult?.let { result ->
                Text(result, modifier = Modifier.padding(top = 8.dp))
            }

            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 32.dp)
                    .clickable { backupExpanded = !backupExpanded },
            ) {
                Text(
                    stringResource(R.string.backup_heading),
                    style = MaterialTheme.typography.titleMedium,
                    modifier = Modifier.weight(1f),
                )
                Icon(
                    if (backupExpanded) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                    contentDescription = stringResource(if (backupExpanded) R.string.collapse else R.string.expand),
                )
            }
            if (backupExpanded) {
                Text(
                    stringResource(R.string.backup_warning),
                    style = MaterialTheme.typography.bodyMedium,
                    modifier = Modifier.padding(top = 4.dp),
                )
                Button(
                    onClick = { exportLauncher.launch(context.getString(R.string.backup_default_filename)) },
                    modifier = Modifier.padding(top = 8.dp),
                ) {
                    Text(stringResource(R.string.export_backup))
                }
                Button(
                    onClick = { importLauncher.launch(arrayOf("application/json")) },
                    modifier = Modifier.padding(top = 8.dp),
                ) {
                    Text(stringResource(R.string.import_backup))
                }
                importResult?.let { result ->
                    Text(result, modifier = Modifier.padding(top = 8.dp))
                }
            }
        }
    }

    if (showAiImportConfirmDialog) {
        AiImportConfirmDialog(
            onConfirm = {
                showAiImportConfirmDialog = false
                performAiImport()
            },
            onDismiss = { showAiImportConfirmDialog = false },
        )
    }
}
